protocol Sender { func send(_ body: String) -> Bool }

struct LoggingSender: Sender {
    let inner: Sender
    let log: (String) -> Void

    func send(_ body: String) -> Bool {
        log("sending \(body.count) bytes")
        return inner.send(body)               // forward to the wrapped value
    }
}
